{
    static void Main()
    {
        // Definir variables
        const double c = 299792458; // velocidad de la luz en m/s
        const double wavelength = 600e-9; // longitud de onda en metros
        double h; // constante de Planck

        // Calcular constante de Planck
        h = 6.62607004e-34 / (c * wavelength);

        // Calcular energía del fotón
        double energyPhoton = h * c;

        // Mostrar resultados
