        // calcula la energía del fotón usando la longitud de onda y la velocidad de la luz
        double photonEnergy = planckConstant * speedOfLight / wavelength;

        // calcula la constante de Planck (h) a partir de la velocidad de la luz y la energía del fotón
        double h = photonEnergy / speedOfLight;

        Console.WriteLine("El valor de la constante de Planck (h) es: {0} J s", h.ToString("0.00E+00"));
        Console.WriteLine("La energía de un fotón con una longitud de onda de 600 nm es: {0} J", photonEnergy.ToString("0.00"));
